try {

// ─── Read rows sent as JSON from browser (SheetJS parsed) ────────────────────
// payload.rows = array-of-arrays: [[row0col0, row0col1,...], [row1col0,...], ...]
const payload  = $input.first().json;
const rawRows  = payload.rows  || [];
const fileName = payload.fileName || 'unknown';

if (rawRows.length < 2) {
  return [{ json: {
    passed: false,
    guardrail_type: 'format',
    critical_errors: [`"${fileName}" has fewer than 2 rows. Add a header row and at least one data row.`],
    warnings: [], stats: { total_rows: 0 }
  }}];
}

// ─── Auto-detect header row ───────────────────────────────────────────────────
// Find the first row whose values include known column keywords
const HEADER_KEYWORDS = ['step','description','status','dri','responsible','notes','email','date','dependency'];
let headerIdx = -1;
for (let i = 0; i < Math.min(rawRows.length, 4); i++) {
  const vals = rawRows[i].map(v => String(v || '').toLowerCase());
  if (vals.some(v => HEADER_KEYWORDS.some(k => v.includes(k)))) {
    headerIdx = i;
    break;
  }
}
if (headerIdx === -1) headerIdx = 0; // fallback: first row

const headers = rawRows[headerIdx].map(v => String(v || '').trim());
const rows    = rawRows.slice(headerIdx + 1)
  .map(r => {
    const obj = {};
    headers.forEach((h, i) => { obj[h || `col_${i}`] = r[i] !== undefined ? String(r[i]) : ''; });
    return obj;
  })
  .filter(r => Object.values(r).some(v => String(v || '').trim() !== ''));

if (rows.length === 0) {
  return [{ json: {
    passed: false,
    guardrail_type: 'format',
    critical_errors: [`No data rows found after the header row in "${fileName}". Add at least one data row below the header.`],
    warnings: [], stats: { total_rows: 0, headers_found: headers }
  }}];
}

const criticalErrors = [];
const warnings       = [];

// ════════════════════════════════════════════════════════════════════════════
// GUARDRAIL 1 — DOMAIN CHECK (Credit Card Processing only)
// ════════════════════════════════════════════════════════════════════════════
const CARD_DOMAIN_KEYWORDS = [
  'credit card','debit card','payment card','card launch','card program','card issuance',
  'card production','card network','card scheme','card processing','card holder','cardholder',
  'bin','bin procurement','bin range','pan','cvv','cvc','card number',
  'issuer','issuing bank','issuing','acquiring','acquirer','card issuer',
  'visa','mastercard','master card','amex','american express','discover','unionpay','rupay','jcb',
  'chargeback','dispute','fraud detection','fraud scoring','fraud prevention',
  'authorization','authorisation','auth request','clearing','settlement','reconciliation',
  'payment processing','payment gateway','payment network',
  'pos terminal','point of sale','atm','contactless','emv','chip and pin',
  'reward','rewards','reward points','reward program','reward redemption',
  'loyalty','loyalty points','loyalty program','loyalty redemption',
  'settlement','net settlement','settlement file','clearing and settlement','settlement report',
  'interchange','interchange fee','tokenization','tokenisation',
  '3d secure','3ds','secure payment','card not present','cnp','card present',
  'credit limit','debit limit','spending limit','card activation'
];

const allText = [
  ...rawRows.flatMap(r => r.map(v => String(v || '').toLowerCase())),
  fileName.toLowerCase()
].join(' ');

const domainMatch = CARD_DOMAIN_KEYWORDS.some(kw => allText.includes(kw));

if (!domainMatch) {
  return [{ json: {
    passed: false,
    guardrail_type: 'domain',
    critical_errors: [
      'DOMAIN GUARDRAIL: This project does not appear to belong to the Credit Card Processing domain. ' +
      'This tracker only accepts projects related to card issuance, acquiring, fraud, disputes, payments, BIN management, or card network operations.'
    ],
    warnings: [], stats: { total_rows: rows.length }
  }}];
}

// ════════════════════════════════════════════════════════════════════════════
// GUARDRAIL 2 — CONTENT CHECK (offensive language)
// ════════════════════════════════════════════════════════════════════════════
const BAD_WORDS = [
  'fuck','fucking','fucked','fucker','shit','shitty','bullshit','horseshit',
  'ass','asshole','arsehole','bitch','bastard','crap','piss','prick','dick',
  'cock','cunt','wanker','twat','tosser',
  'nigger','nigga','faggot','fag','dyke','tranny','spic','kike','chink',
  'wetback','raghead','towelhead','cracker','gook','nip','wop','honky',
  'beaner','coon','sandnigger','zipperhead','nazi','kkk','jihadi',
  'kill you','murder','rape','terrorist','bomb','shoot',
  'suicide','self-harm','self harm','porn','pornography','xxx','nude','naked'
];

const allCells = rawRows.flatMap(r => r.map(v => String(v || '').toLowerCase()));
const badWordsFound = [];
for (const cell of allCells) {
  for (const word of BAD_WORDS) {
    let matched = false;
    if (word.includes('-') || word.includes(' ')) {
      matched = cell.includes(word);
    } else {
      const regex = new RegExp('\\b' + word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
      matched = regex.test(cell);
    }
    if (matched && !badWordsFound.includes(word)) badWordsFound.push(word);
  }
}

if (badWordsFound.length > 0) {
  return [{ json: {
    passed: false,
    guardrail_type: 'content',
    critical_errors: [
      `CONTENT GUARDRAIL: Inappropriate or offensive content detected (${badWordsFound.length} flagged term(s)). ` +
      'All content must be professional and workplace-appropriate. Please review every cell and re-upload.'
    ],
    warnings: [], stats: { total_rows: rows.length, flagged_terms: badWordsFound.length }
  }}];
}

// ════════════════════════════════════════════════════════════════════════════
// STRUCTURAL VALIDATION
// ════════════════════════════════════════════════════════════════════════════
const REQUIRED_COLS = [
  { key: 'step',        patterns: ['step number','step no','step#','step num','steps','#'] },
  { key: 'description', patterns: ['step description','description','task','activity'] },
  { key: 'dri_name',    patterns: ['dri name','responsible party','dri','owner','assignee','responsible'] },
  { key: 'dri_email',   patterns: ['dri email','email','dri email address','email address'] },
  { key: 'est_start',   patterns: ['estimated start','est start','start date','est start date'] },
  { key: 'est_end',     patterns: ['estimated end','est end','end date','est end date','due date','estimated date'] },
  { key: 'status',      patterns: ['status','current status'] }
];

const VALID_STATUSES = ['to do','in progress','done','blocked','todo','complete','completed','not started'];
const colMap = {};
for (const col of REQUIRED_COLS) {
  const found = headers.find(h => col.patterns.some(p => h.toLowerCase().trim().includes(p)));
  if (found) {
    colMap[col.key] = found;
  } else {
    criticalErrors.push(`Required column missing: "${col.patterns[0]}" not found. Found headers: ${headers.filter(h=>h).join(', ')}`);
  }
}

if (rows.length < 1) {
  criticalErrors.push(`Too few rows: only ${rows.length} data row(s) found. Minimum 1 required.`);
}

let missingCells = 0, invalidDates = 0, invalidStatuses = 0, invalidEmails = 0;
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const dateRe  = /^\d{1,2}[\/\-\.]\d{1,2}[\/\-\.]\d{2,4}$/;

rows.forEach((row, idx) => {
  const rowNum = idx + headerIdx + 2;

  for (const [key, col] of Object.entries(colMap)) {
    const val = String(row[col] || '').trim();
    if (!val) {
      missingCells++;
      if (missingCells <= 5) criticalErrors.push(`Row ${rowNum}: "${col}" is empty — required field.`);
    }
  }

  if (colMap.status) {
    const sv = String(row[colMap.status] || '').trim().toLowerCase();
    if (sv && !VALID_STATUSES.includes(sv)) {
      invalidStatuses++;
      if (invalidStatuses <= 3) criticalErrors.push(`Row ${rowNum}: Invalid status "${row[colMap.status]}". Must be: To Do, In Progress, Done, Blocked.`);
    }
  }

  if (colMap.dri_email) {
    const ev = String(row[colMap.dri_email] || '').trim();
    if (ev && !emailRe.test(ev)) {
      invalidEmails++;
      if (invalidEmails <= 3) warnings.push(`Row ${rowNum}: Invalid email "${ev}".`);
    }
  }
});

if (missingCells  > 5) criticalErrors.push(`...and ${missingCells - 5} more missing required cells.`);
if (invalidStatuses > 3) criticalErrors.push(`...and ${invalidStatuses - 3} more invalid statuses.`);
if (invalidEmails  > 3) warnings.push(`...and ${invalidEmails - 3} more invalid emails.`);

return [{ json: {
  passed:          criticalErrors.length === 0,
  guardrail_type:  null,
  critical_errors: criticalErrors,
  warnings,
  stats: {
    total_rows:       rows.length,
    headers_found:    headers,
    missing_cells:    missingCells,
    invalid_statuses: invalidStatuses,
    invalid_emails:   invalidEmails
  }
}}];

} catch (err) {
  return [{ json: {
    passed: false,
    guardrail_type: 'error',
    critical_errors: ['Validation engine error: ' + err.message],
    warnings: [], stats: {}
  }}];
}

const v = $input.first().json;
const warnings = v.warnings || [];
const stats = v.stats || {};

const summary = [
  `✅ Validation passed — your Excel file is ready to process.`,
  ``,
  `📊 Summary:`,
  `   • ${stats.total_rows} data rows detected`,
  `   • ${stats.headers_detected ? stats.headers_detected.length : '?'} columns found`,
  stats.optional_cols_found && stats.optional_cols_found.length > 0
    ? `   • Optional columns detected: ${stats.optional_cols_found.join(', ')}`
    : `   • No optional columns (Dependencies, Security Flag, Notes) — that is fine`,
  ``,
  warnings.length > 0
    ? `⚠️ Warnings (non-blocking):\n${warnings.map(w => `   • ${w}`).join('\n')}`
    : `✅ No warnings.`,
  ``,
  `▶ Proceeding to generate your project tracker...`
].join('\n');

return [{ json: {
  status: 'success',
  reply: summary,
  passed: true,
  warnings: v.warnings,
  stats: v.stats
}}];

const v = $input.first().json;
const errors       = v.critical_errors || [];
const warnings     = v.warnings || [];
const stats        = v.stats || {};
const guardrailType = v.guardrail_type;

let prompt;

if (guardrailType === 'domain') {
  prompt = `A user tried to upload an Excel project file to the Credit Card Processing Multi-Project Tracker but it was rejected because the project content does not match the Credit Card Processing domain.

REJECTION REASON:
${errors[0]}

Write a polite, professional message explaining:
1. That this tool is purpose-built for credit card processing, issuing, acquiring, fraud, disputes, and payment operations projects
2. The type of projects that ARE accepted (give 3-4 examples: BIN Procurement, Fraud Detection, Chargeback Management, Card Network Migration)
3. That they should speak to their administrator if they believe this is a mistake

Keep under 150 words. Be respectful — do not make the user feel they did something wrong.`;
} else if (guardrailType === 'content') {
  prompt = `A user tried to upload an Excel project file to the Multi-Project Tracker but it was rejected because the file contained inappropriate or offensive content.

REJECTION REASON:
${errors[0]}

Write a firm but professional message explaining:
1. That all uploaded content must meet workplace and professional standards
2. That the file contained language that does not meet those standards (do NOT reveal which words were found)
3. That they should review and clean all cells in the spreadsheet and re-upload
4. That repeated violations may be escalated to their manager

Keep under 120 words. Be firm but not accusatory.`;
} else {
  const errorList = errors.map((e, i) => `${i+1}. ${e}`).join('\n');
  const warnList  = warnings.length > 0 ? warnings.map((w, i) => `${i+1}. ${w}`).join('\n') : 'None';

  prompt = `An Excel file was uploaded to the Multi-Project Tracker and failed structural validation.

CRITICAL ERRORS (must fix):
${errorList}

WARNINGS (recommended):
${warnList}

FILE STATS:
- Total rows: ${stats.total_rows}
- Missing required cells: ${stats.missing_cells}
- Invalid dates: ${stats.invalid_dates}
- Invalid status values: ${stats.invalid_statuses}

Write a clear, friendly message telling the user exactly what to fix and how. Use bullet points. Reference row numbers and column names. End with encouragement to re-upload. Keep under 250 words.`;
}

return [{ json: {
  prompt,
  passed: false,
  guardrail_type: guardrailType,
  critical_errors: errors,
  warnings,
  stats
}}];

const item = $input.first().json;
return [{ json: {
  status:   'success',
  passed:   true,
  reply:    item.reply,
  warnings: item.warnings || [],
  stats:    item.stats || {},
  next_step: 'proceed_to_generation',
  timestamp: new Date().toISOString()
}}];

const apiResp  = $input.first().json;
const valData  = $('Build Error Context').first().json;

// Claude may have failed — fall back to raw error list
let friendlyMsg;
if (apiResp.content && apiResp.content[0] && apiResp.content[0].text) {
  friendlyMsg = apiResp.content[0].text;
} else {
  // Build a clear fallback message without Claude
  const errors = valData.critical_errors || [];
  const type   = valData.guardrail_type;
  if (type === 'domain') {
    friendlyMsg = '❌ Domain rejected: This project does not belong to the Credit Card Processing domain.\n\n' +
      'This tool only accepts card issuance, acquiring, fraud, dispute, payment, BIN, or reward projects.\n\n' +
      'Please verify your project content and re-upload.';
  } else if (type === 'content') {
    friendlyMsg = '❌ Content rejected: Your spreadsheet contains inappropriate or offensive language.\n\n' +
      'All content must be professional and workplace-appropriate.\n\n' +
      'Please review every cell, remove flagged language, and re-upload.';
  } else if (type === 'format') {
    friendlyMsg = '❌ File error: Could not read your Excel file.\n\n' +
      'Please ensure the file is a valid .xlsx or .xls format and try again.';
  } else {
    friendlyMsg = '❌ Validation failed with ' + errors.length + ' issue(s):\n\n' +
      errors.map(e => '• ' + e).join('\n') +
      (valData.warnings && valData.warnings.length
        ? '\n\nWarnings:\n' + valData.warnings.map(w => '• ' + w).join('\n')
        : '');
  }
}

return [{ json: {
  status:          'error',
  passed:          false,
  reply:           friendlyMsg,
  guardrail_type:  valData.guardrail_type,
  critical_errors: valData.critical_errors,
  warnings:        valData.warnings || [],
  stats:           valData.stats    || {},
  next_step:       'fix_and_reupload',
  timestamp:       new Date().toISOString()
}}];

return [{ json: {
  passed: false,
  guardrail_type: 'format',
  critical_errors: ['Could not read the uploaded file. Please ensure it is a valid .xlsx or .xls Excel file and try again.'],
  warnings: [],
  stats: {}
}}];
